<?php

namespace Database\Factories;

use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * @extends \Illuminate\Database\Eloquent\Factories\Factory<\App\Models\Guest>
 *
 * `guest_code` is generated by the model's creating hook, so it is not set
 * here. `invitation_id` must be supplied by the caller (or an active
 * TenantContext must exist) - the model fails closed otherwise.
 */
class GuestFactory extends Factory
{
    public function definition(): array
    {
        return [
            'name' => fake()->name(),
            'city' => fake()->city(),
            'category' => fake()->randomElement(['Tamu Maul', 'Tamu Kahfi', 'Keluarga', null]),
            'quota' => 1,
            'is_rsvp' => false,
            'checkin_status' => 'not_arrived',
        ];
    }

    public function arrived(): static
    {
        return $this->state(fn () => [
            'checkin_status' => 'arrived',
            'checked_in_at' => now(),
            'actual_guest_count' => 1,
        ]);
    }
}
